  --text: #e6edf3;
  --muted: #a3b1c2;
  --accent: #10b981;
  --border: #1e293b;
  --input-bg: #0a1220;
  --btn1-from: #16a34a;
  --btn1-to: #15803d;
  --btn2-from: #1b2540;
  --btn2-to: #151c31;
}

body.theme-light {
  --bg: #f8fafc;
  --panel: #ffffff;
  --panel-2: #ffffff;
