};

// Extend Jest matchers
expect.extend({
  toBePending(received) {
    const isPending = received instanceof Promise && 
      received.then && 
      !received._settled;
    
    return {
      pass: isPending,
      message: () => `expected promise to be pending`,
    };
  },
});

